import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 deposit, uint256 withdraw) public {
        // Bound inputs to reasonable ranges
        deposit = bound(deposit, 0, 100 ether);
        withdraw = bound(withdraw, 0, 100 ether);

        // Ensure enough ether for caller
        vm.deal(caller, deposit + withdraw);

        // Prank as caller
        vm.prank(caller);
        // Deposit some ether (may fail if deposit < MinDeposit of 1 ether)
        if (deposit > 0.99 ether) {
            (bool ok, ) = address(c).call{value: deposit}("");
            if (ok) {
                c.Deposit{value: 0}(); // The deposit already happened via receive, but if we call Deposit separately with value, it's passed; to avoid double, just call with 0 value
            }
        }

        // Record caller's balance before CashOut
        uint256 balanceBefore = c.balances(caller);

        vm.prank(caller);
        // Call CashOut
        (bool success, ) = address(c).call(
            abi.encodeWithSelector(c.CashOut.selector, withdraw)
        );

        // If CashOut reverted, balance should be unchanged
        if (!success) {
            assertTrue(c.balances(caller) == balanceBefore, "Balance unchanged on revert");
        } else {
            // If CashOut succeeded, balance must be <= balanceBefore (decrease or stay same)
            assertTrue(c.balances(caller) <= balanceBefore, "Balance did not increase after CashOut");
        }
    }
}

