pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address beneficiary, uint256 depositAmount, uint256 withdrawAmount) public {
        // Restrict depositAmount to > MinDeposit so deposit is meaningful for reference
        uint256 minDep = c.MinDeposit();
        vm.assume(depositAmount > minDep);
        // bound withdrawAmount to a large range but keep it reasonable
        uint256 wd = bound(withdrawAmount, 0, depositAmount * 2);

        // Give beneficiary enough ether to deposit
        vm.deal(beneficiary, depositAmount);

        // Deposit by the beneficiary
        vm.prank(beneficiary);
        c.Deposit{value: depositAmount}();

        // Record balance before CashOut
        uint256 balanceBefore = c.balances(beneficiary);

        // Attempt CashOut
        vm.prank(beneficiary);
        (bool ok,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", wd));

        // For the reference C, if CashOut succeeds, the withdrawal must not exceed the balance before
        // The invariant: after a successful CashOut, the contract's total balance (eth) plus caller's balance
        // cannot exceed the sum of initial deposits.  But simpler: if caller's balance before CashOut is b, and
        // they try to withdraw w, the transaction must revert if w > b.
        // For the mutant (which never adds to balance), b remains 0 for a new beneficiary; so a withdrawal of 
        // any positive w succeeds, breaking this invariant.

        // Assert: if CashOut succeeded, then wd <= balanceBefore
        if (ok) {
            assertTrue(wd <= balanceBefore, "CashOut succeeded but withdrawal exceeded balance");
        } else {
            // If it reverted, it's permissible only if wd > balanceBefore
            assertTrue(wd > balanceBefore, "CashOut reverted but withdrawal was within balance");
        }
    }
}

